-- Dados do currículo Lattes da coordenadora (gerado em 10/11/2026). Pode ser executado mais de uma vez.
begin;
update public.pessoas set onde_esta='Mestrado em Engenharia de Processos pela Universidade Tiradentes' where slug='leonardo-aprigio-nascimento' and onde_esta like 'Parceiro nos projetos%';
update public.pessoas set ano_entrada=coalesce(ano_entrada,2019) where slug='franciele-da-silva-mota';
update public.pessoas set bio = bio || ' Pela UFS, foi campeã (2016) e terceira colocada (2015) na categoria IEEE Very Small da Competição Latino-Americana e Brasileira de Robótica.' where slug='stephanie-kamarry-alves-de-sousa' and bio not like '%Very Small%';
update public.projetos set ano_inicio=coalesce(ano_inicio,2020), ano_fim=coalesce(ano_fim,2021) where slug='modelagem-e-controle-de-um-quadricoptero';
update public.projetos set ano_inicio=coalesce(ano_inicio,2018), ano_fim=coalesce(ano_fim,2019), descricao=case when descricao='' then 'Desenvolvimento de um sistema autônomo que permite a um time de robôs móveis navegar em formação, de forma cooperativa.' else descricao end where slug='navegacao-em-formacao-de-multiplos-robos';
update public.projetos set ano_inicio=coalesce(ano_inicio,2018), ano_fim=coalesce(ano_fim,2019) where slug='robotica-para-ensinar-matematica-em-ongs';
update public.projetos set ano_inicio=coalesce(ano_inicio,2019), ano_fim=coalesce(ano_fim,2020) where slug='labic-itinerante';
update public.projetos set ano_inicio=coalesce(ano_inicio,2021), ano_fim=coalesce(ano_fim,2022) where slug='veiculo-aereo-nao-tripulado-do-tipo-quadrotor';
update public.projetos set ano_inicio=coalesce(ano_inicio,2022), descricao=case when descricao='' then 'Robô de código aberto feito com impressão 3D, apresentado no congresso internacional OCEANS 2023, em Limerick, na Irlanda.' else descricao end where slug='peixe-robo';
update public.projetos set ano_inicio=coalesce(ano_inicio,2024), fomento=case when fomento='' then 'PIBIC/CNPq' else fomento end where slug='submarino';
update public.conquistas set descricao='Programa de computador, registro BR512026002928-7, de 05/05/2026.' where tipo='SOFTWARE' and titulo like 'AquaFeed:%' and descricao='';
update public.conquistas set autores='Catuxe Varjão de Santana Oliveira, Eddie Fernandes de Jesus Menezes, Felipe Jovino dos Santos, Gabriel do Nascimento Santos Silva, José Matheus Oliveira Cavalcante, Stephanie Kamarry Alves de Sousa' where tipo='ARTIGO' and titulo ilike 'Acesso a formação em Inteligência Artificial%' and autores='';
commit;
select (select count(*) from public.pessoas) pessoas, (select count(*) from public.projetos) projetos, (select count(*) from public.conquistas) conquistas, (select count(*) from public.conquistas where tipo='TCC') tccs, (select count(*) from public.conquistas where tipo='ARTIGO') artigos, (select count(*) from public.conquistas where tipo='SOFTWARE') softwares, (select count(*) from public.parceiros) parceiros, (select count(*) from public.marcos) marcos, (select count(*) from public.projeto_pessoas) equipe;
